  methods: {
    async logout() {
      try {
        // Call the logout API endpoint
        await axios.post('/users/api/logout/');
        localStorage.removeItem('token');
        this.router.push('/login');
      } catch (error) {
        console.error('Logout failed:', error);
        localStorage.removeItem('token');
        this.router.push('/login');
      }
    },
    isActive(route) {
      return this.$route.path === route;
    }
  },
